/**
 * The curation queue, on `src/api/schema.d.ts` — generated by `make types` from
 * the real pydantic models and held to the tree by `make lint-generated`.
 *
 * `kind`, `resolution` and `suggestion` are `Literal` unions on the backend
 * model, so the generated type carries them and the vocabularies below are
 * derived rather than restated. The hand-written copy had already drifted once
 * on exactly this: `related` had been emitted since the relate verdict shipped
 * and was missing from `Resolution`, so a related conflict typed as `null`.
 * Deriving them is what makes that impossible rather than unlikely.
 */

import type { components } from '@/api/schema'

type Schemas = components['schemas']

export type Conflict = Schemas['Conflict']

export type ConflictKind = NonNullable<Conflict['kind']>

export type Resolution = NonNullable<Conflict['resolution']>

export type PredicateOption = Schemas['PredicateOption']

/** Which predicates are well-typed for a pair, in each direction. Generated
 *  from the ontology so the offered choices and `check_relation` cannot drift.
 *  The types are the RESOLVED ones — a pair whose side was merged away is
 *  judged as what it is now, not as the tombstone the row was filed with. */
export type ConflictOptions = Schemas['ConflictOptions']

export type Merge = Schemas['Merge']

export type MergeList = Schemas['MergeList']

/**
 * `pending_definitions` counts SURFACES awaiting a decision — the unit the
 * queue serves. `pending_rebuild` counts changes a rebuild would apply right
 * now, so merging two uncorroborated entities adds nothing to it: neither was
 * ever in the graph. `blocked_relations` counts curated relationships that
 * cannot project because an endpoint is uncorroborated, which corroboration
 * fixes and a rebuild does not.
 */
export type CurationStatus = Schemas['CurationStatus']

// ── the definitions queue ────────────────────────────────────────────
//
// These were declared inside `DefinitionQueue.vue` as three local interfaces,
// which is how the component came to be missing `decided` — a field the server
// has been sending on every item.

/** One surface awaiting a decision. The unit of work is the SURFACE, not the
 *  expansion: `FCC` is one question with several possible answers, not several
 *  questions. */
export type QueueItem = Schemas['QueueItem']

/** One candidate expansion for a surface, with the evidence behind it. */
export type QueueReading = Schemas['QueueReading']

/** What the adjudicator proposes. It fills a button; it never presses one. */
export type QueueSuggestion = Schemas['QueueSuggestion']

/** `GET /curation/definitions`. */
export type DefinitionQueue = Schemas['DefinitionQueue']

/** `GET /curation/conflicts`. Carries `counts` per kind and `total_open`
 *  alongside the page, so the header badge and the queue agree without a second
 *  request. */
export type ConflictList = Schemas['ConflictList']

/** `POST /curation/rebuild` — the Neo4j projection, reconstructed from the
 *  `assertions` table. Invariant 1 is what makes this safe to offer as a
 *  button: the graph is rebuildable, so losing it is never data loss. */
export type RebuildResult = Schemas['RebuildResult']
